import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { invoiceTotals } from '../src/invoices.js';

test('createCreditNote creates a credit note for an issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Partial refund', date: '2025-01-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-0001');
  assert.equal(result.value.invoiceNumber, issued.value.number);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.amount, 5000);
  assert.equal(result.value.reason, 'Partial refund');
  assert.equal(result.value.date, '2025-01-20');
});

test('createCreditNote works for partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 5000, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const result = createCreditNote(payment.value, { amount: 2000, reason: 'Adjustment', date: '2025-01-25' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-0001');
});

test('createCreditNote works for paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const payment = recordPayment(issued.value, { amount: 10920, date: '2025-01-20' });
  assert.equal(payment.ok, true);

  const result = createCreditNote(payment.value, { amount: 5000, reason: 'Overpayment refund', date: '2025-01-25' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-0001');
});

test('createCreditNote fails for draft invoices (NOT_ISSUED)', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);

  const result = createCreditNote(inv.value, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_ISSUED');
});

test('createCreditNote fails with AMOUNT_INVALID for non-positive amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const badAmounts = [0, -1000, 1.5, NaN, Infinity];

  for (const amount of badAmounts) {
    const result = createCreditNote(issued.value, { amount, reason: 'Refund', date: '2025-01-20' }, []);
    assert.equal(result.ok, false, `amount ${amount} should be invalid`);
    assert.equal(result.error, 'AMOUNT_INVALID');
  }
});

test('createCreditNote fails with CREDIT_TOO_HIGH if amount exceeds invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const invoiceTotal = invoiceTotals(issued.value).total;
  const result = createCreditNote(issued.value, { amount: invoiceTotal + 1, reason: 'Refund', date: '2025-01-20' }, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'CREDIT_TOO_HIGH');
});

test('createCreditNote validates date format (DATE_INVALID)', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2025-1-20' }, []);

  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('createCreditNote allows amount equal to invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const invoiceTotal = invoiceTotals(issued.value).total;
  const result = createCreditNote(issued.value, { amount: invoiceTotal, reason: 'Full refund', date: '2025-01-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.amount, invoiceTotal);
});

test('createCreditNote numbers start at 0001 for a new year', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-0001');
});

test('createCreditNote increments counter for multiple credit notes', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv1.ok, true);
  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-16',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv2.ok, true);
  const issued2 = issueInvoice(inv2.value, ['INV-2025-0001']);
  assert.equal(issued2.ok, true);

  const cn1 = createCreditNote(issued1.value, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, []);
  assert.equal(cn1.ok, true);
  assert.equal(cn1.value.number, 'CN-2025-0001');

  const cn2 = createCreditNote(issued2.value, { amount: 5000, reason: 'Refund', date: '2025-01-21' }, ['CN-2025-0001']);
  assert.equal(cn2.ok, true);
  assert.equal(cn2.value.number, 'CN-2025-0002');
});

test('createCreditNote tracks separately from invoice numbers', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003']);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-0001');
});

test('createCreditNote resets counter by year', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2026-01-20' }, ['CN-2025-0005']);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2026-0001');
});

test('createCreditNote pads counter to 4 digits', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const existingNumbers = Array.from({ length: 100 }, (_, i) => `CN-2025-${String(i + 1).padStart(4, '0')}`);
  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, existingNumbers);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-0101');
});

test('createCreditNote handles counter > 9999', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const existingNumbers = ['CN-2025-9999', 'CN-2025-10000'];
  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Refund', date: '2025-01-20' }, existingNumbers);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2025-10001');
});

test('createCreditNote includes all required fields', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const result = createCreditNote(issued.value, { amount: 5000, reason: 'Wrong item shipped', date: '2025-01-20' }, []);

  assert.equal(result.ok, true);
  const cn = result.value;
  assert(cn.number);
  assert.equal(cn.invoiceNumber, issued.value.number);
  assert.equal(cn.customerId, 'C-001');
  assert.equal(cn.amount, 5000);
  assert.equal(cn.reason, 'Wrong item shipped');
  assert.equal(cn.date, '2025-01-20');
});

test('createCreditNote with various amounts below total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const invoiceTotal = invoiceTotals(issued.value).total;
  const testAmounts = [1, 100, 1000, invoiceTotal - 1];

  for (const amount of testAmounts) {
    const result = createCreditNote(issued.value, { amount, reason: 'Refund', date: '2025-01-20' }, []);
    assert.equal(result.ok, true, `amount ${amount} should be valid`);
    assert.equal(result.value.amount, amount);
  }
});

